        nums = sorted(nums)
    elif draw(st.integers(0, 4)) == 0:
        nums = sorted(nums, reverse=True)
    if draw(st.booleans()):
        k = draw(st.integers(1, 30))
    else:
        k = draw(st.integers(1, 10**9))
    return json.dumps(nums) + "\n" + json.dumps(k) + "\n"

def validate(inp):
    lines = inp.split("\n")
    lines = [l for l in lines if l.strip() != ""]
    if len(lines) != 2:
        return False
    nums = json.loads(lines[0])
    k = json.loads(lines[1])
    if not isinstance(nums, list) or not isinstance(k, int) or isinstance(k, bool):
        return False
    n = len(nums)
    if not (1 <= n <= 10**5):
        return False
    if not all(isinstance(x, int) and not isinstance(x, bool) and 1 <= x <= 10**9 for x in nums):
        return False
    if not (isinstance(k, int) and 1 <= k <= 10**9):
        return False
    return True

def ref(inp):
    lines = [l for l in inp.split("\n") if l.strip() != ""]
    nums = json.loads(lines[0])
    k = json.loads(lines[1])
    n = len(nums)
    count = 0
    # For each subarray, the minimum total number of increments needed to make it
    # non-decreasing: the pointwise-minimal target is the running prefix maximum,
    # so cost = sum(prefix_max_i - b_i). Count subarrays with cost <= k.
    for i in range(n):
        for j in range(i, n):
            sub = nums[i:j + 1]
            cur_max = None
            cost = 0
            for x in sub:
                if cur_max is None or x > cur_max:
                    cur_max = x
                cost += cur_max - x
